#[derive(Clone, Copy, ValueEnum)]
enum UsageBy {
    Agent,
    Mission,
    Step,
    Model,
    Account,
    Host,
}

impl UsageBy {
    const ALL: [Self; 6] = [
        Self::Agent,
        Self::Mission,
        Self::Step,
        Self::Model,
        Self::Account,
        Self::Host,
    ];

    /// The report row field this grouping reads.
    fn field(self) -> &'static str {
        match self {
            Self::Agent => "agent",
            Self::Mission => "mission_run",
            Self::Step => "step",
            Self::Model => "model",
            Self::Account => "account",
            Self::Host => "host",
        }
    }

    fn label(self) -> &'static str {
        match self {
            Self::Mission => "mission",
            other => other.field(),
        }
    }
}

